{
  "name": "Daily weather summary",
  "settings": { "timezone": "Asia/Kolkata" },
  "nodes": [
    { "name": "Schedule Trigger", "type": "n8n-nodes-base.scheduleTrigger", "typeVersion": 1.2, "position": [0, 0],
      "parameters": { "rule": { "interval": [ { "field": "cronExpression", "expression": "0 8 * * 1-5" } ] } } },
    { "name": "HTTP Request", "type": "n8n-nodes-base.httpRequest", "typeVersion": 4.2, "position": [220, 0],
      "parameters": { "url": "https://api.open-meteo.com/v1/forecast?latitude=12.97&longitude=77.59&current=temperature_2m,wind_speed_10m" } },
    { "name": "Edit Fields", "type": "n8n-nodes-base.set", "typeVersion": 3.4, "position": [440, 0],
      "parameters": { "assignments": { "assignments": [
        { "id": "a1", "name": "summary", "type": "string",
          "value": "=Bengaluru at {{ $now.toFormat('HH:mm') }}: {{ $json.current.temperature_2m }}°C, wind {{ $json.current.wind_speed_10m }} km/h" } ] } } },
    { "name": "Gmail", "type": "n8n-nodes-base.gmail", "typeVersion": 2.1, "position": [660, 0],
      "parameters": { "sendTo": "team@example.com", "subject": "Daily weather", "emailType": "text", "message": "={{ $json.summary }}" } }
  ],
  "connections": {
    "Schedule Trigger": { "main": [[ { "node": "HTTP Request", "type": "main", "index": 0 } ]] },
    "HTTP Request": { "main": [[ { "node": "Edit Fields", "type": "main", "index": 0 } ]] },
    "Edit Fields": { "main": [[ { "node": "Gmail", "type": "main", "index": 0 } ]] }
  }
}

// Input items come from Extract From File (CSV): { customer, order_id, amount }
const totals = {};

for (const item of $input.all()) {
  const customer = (item.json.customer || 'Unknown').trim();
  const amount = Number(item.json.amount) || 0; // CSV gives strings
  if (!totals[customer]) {
    totals[customer] = { total: 0, orders: 0 };
  }
  totals[customer].total += amount;
  totals[customer].orders += 1;
}

return Object.entries(totals).map(([customer, t]) => ({
  json: {
    customer,
    orders: t.orders,
    total: Math.round(t.total * 100) / 100,
  },
}));

// No-code alternative: Summarize node
//   Fields to Split By: customer
//   Aggregation: Sum of amount, Count of order_id
// Later node reference: {{ $('Read Orders CSV').first().json.fileName }}

// Input: booked orders from the If node's true branch
const items = $input.all();

let totalBooked = items.length;
let bookedSum = 0;

for (const item of items) {
  bookedSum += Number(item.json.orderPrice) || 0;
}

// Return ONE summary item
return [
  {
    json: {
      totalBooked,
      bookedSum,
    },
  },
];

// Discord node message (expression):
// This week we've {{ $json.totalBooked }} booked orders
// with a total value of {{ $json.bookedSum }}.

// Mode: Run Once for All Items
const d = $input.first().json;

// Failure inside the trigger node has a different shape
if (d.trigger) {
  return [{ json: {
    text: `🚨 Trigger failed in "${d.workflow.name}"\n` +
          `Error: ${d.trigger.error.message}`
  }}];
}

const e = d.execution;
const text = [
  `🚨 Workflow failed: ${d.workflow.name} (id ${d.workflow.id})`,
  `Failing node: ${e.lastNodeExecuted}`,
  `Error: ${e.error.message}`,
  `Mode: ${e.mode}`,
  `Open run: ${e.url}`
].join('\n');

return [{ json: { text } }];
